using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Collections.Generic;
using System.Diagnostics;
using System.Management;
using Microsoft.Win32;
using System.Reflection;
using System.Security.Cryptography;
namespace FramePilot {
 public sealed class DriverEntry { public string Device,Provider,Version,Date,Inf,Signed; }
 public sealed class InstalledEntry { public string Name,Publisher,Version,Location,Key; public long Size; public override string ToString(){return Name;} }
 public static class Inventory {
  public static List<DriverEntry> Drivers(){var list=new List<DriverEntry>();using(var search=new ManagementObjectSearcher("SELECT DeviceName,DriverProviderName,DriverVersion,DriverDate,InfName,IsSigned FROM Win32_PnPSignedDriver"))using(var rows=search.Get())foreach(ManagementObject row in rows)using(row){string date=Convert.ToString(row["DriverDate"]);list.Add(new DriverEntry{Device=Convert.ToString(row["DeviceName"]),Provider=Convert.ToString(row["DriverProviderName"]),Version=Convert.ToString(row["DriverVersion"]),Date=date.Length>=8?date.Substring(0,8):date,Inf=Convert.ToString(row["InfName"]),Signed=Convert.ToString(row["IsSigned"])});}foreach(var item in list)if(string.IsNullOrWhiteSpace(item.Device))item.Device="Unnamed device record";return list.OrderBy(x=>x.Device).ToList();}
  public static List<InstalledEntry> Apps(){var list=new List<InstalledEntry>();foreach(var hive in new[]{RegistryHive.LocalMachine,RegistryHive.CurrentUser})foreach(var view in new[]{RegistryView.Registry64,RegistryView.Registry32})using(var root=RegistryKey.OpenBaseKey(hive,view))using(var parent=root.OpenSubKey(@"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall")){if(parent==null)continue;foreach(string name in parent.GetSubKeyNames())try{using(var key=parent.OpenSubKey(name)){if(key==null||Convert.ToString(key.GetValue("SystemComponent"))=="1")continue;string display=Convert.ToString(key.GetValue("DisplayName"));if(string.IsNullOrWhiteSpace(display))continue;long size;long.TryParse(Convert.ToString(key.GetValue("EstimatedSize")),out size);list.Add(new InstalledEntry{Name=display,Version=Convert.ToString(key.GetValue("DisplayVersion")),Publisher=Convert.ToString(key.GetValue("Publisher")),Location=Convert.ToString(key.GetValue("InstallLocation")),Size=Math.Max(0,size)*1024L,Key=hive+"/"+view+"/"+name});}}catch(System.Security.SecurityException){}}return list.GroupBy(x=>x.Name+"|"+x.Version+"|"+x.Location).Select(x=>x.First()).OrderByDescending(x=>x.Size).ThenBy(x=>x.Name).ToList();}
  public static string DriverReport(IEnumerable<DriverEntry> rows){var b=new StringBuilder("Device\tProvider\tVersion\tDate (YYYYMMDD)\tINF\tSigned\r\n");foreach(var d in rows)b.AppendLine(string.Join("\t",new[]{d.Device,d.Provider,d.Version,d.Date,d.Inf,d.Signed}.Select(x=>(x??"").Replace("\t"," ").Replace("\r"," ").Replace("\n"," "))));return b.ToString();}
 }
 public static class Releases {
  public static string Hash(string path){using(var sha=SHA256.Create())using(var f=File.OpenRead(path))return BitConverter.ToString(sha.ComputeHash(f)).Replace("-","").ToLowerInvariant();}
  public static Version Validate(string path,bool requireNewer){if(!File.Exists(path)||new FileInfo(path).Length>100*1024*1024||!string.Equals(Path.GetExtension(path),".exe",StringComparison.OrdinalIgnoreCase))throw new Exception("Choose a FramePilot EXE under 100 MB.");var a=AssemblyName.GetAssemblyName(path);var f=FileVersionInfo.GetVersionInfo(path);if(a.Name!="FramePilot"||f.ProductName!="FramePilot")throw new Exception("This file is not a FramePilot release.");if(requireNewer&&a.Version<=Assembly.GetExecutingAssembly().GetName().Version)throw new Exception("Select a newer release than the running version.");return a.Version;}
  public static string Quote(string arg){if(arg.IndexOf('"')>=0||arg.EndsWith("\\"))throw new Exception("Unsupported path argument.");return "\""+arg+"\"";}
  public static int Swap(string[] args){try{if(args.Length!=6)return 2;int pid=int.Parse(args[1]);string target=Path.GetFullPath(args[2]),candidate=Path.GetFullPath(args[3]),hash=args[4],backup=target+".previous";long ticks=long.Parse(args[5]);try{using(var p=Process.GetProcessById(pid)){if(p.StartTime.ToUniversalTime().Ticks!=ticks)return 3;if(!p.WaitForExit(60000))return 4;}}catch(ArgumentException){}ReplaceRelease(target,candidate,hash);Process.Start(new ProcessStartInfo(target){UseShellExecute=true});return 0;}catch(Exception e){System.Windows.Forms.MessageBox.Show("Update was not completed. Your previous EXE is retained.\r\n"+e.Message,"FramePilot update");return 1;}}
  public static void ReplaceRelease(string target,string candidate,string hash){Validate(candidate,false);Validate(target,false);if(Hash(candidate)!=hash)throw new Exception("Release checksum mismatch; original retained.");string temp=target+".update-"+Guid.NewGuid().ToString("N");try{File.Copy(candidate,temp);if(Hash(temp)!=hash)throw new Exception("Staged checksum mismatch; original retained.");File.Replace(temp,target,target+".previous",true);}finally{if(File.Exists(temp))File.Delete(temp);}}
  public const string Notes="FRAMEPILOT 3.1.0 | Easier everyday use\r\n\r\n- Faster live monitoring: CPU/RAM every second, GPU every two seconds.\r\n- Large color-coded FPS and latency badges; explicit unmeasured gain/loss.\r\n- Steam/Epic/GOG discovery, bounded game-folder EXE scan and saved custom links.\r\n- Optional startup apps separated from protected entries; more launchers supported.\r\n- Live Windows Update driver availability check with clear available/unknown states.\r\n- App storage sizes shown in familiar decimal GB.\r\n\r\nFRAMEPILOT 3.0.0 | Drivers, storage and portable releases\r\n\r\n- Installed PnP driver inventory: device, provider, version, date, INF, signature flag.\r\n- NVIDIA App integration, Windows Update / optional drivers, AMD and OEM support.\r\n- Export third-party driver packages with Windows PnPUtil; Device Manager rollback guide.\r\n- Drive capacity and searchable installed desktop apps, sorted by reported size.\r\n- Removal through Windows Installed apps; Store apps also handled there.\r\n- Per-control FPS / latency potential labels; no fabricated performance numbers.\r\n- Embedded FP icon, portable EXE, desktop copy, local release update and previous EXE recovery.\r\n- Patch notes included inside the EXE. Hardware guidance now works on friends' PCs.\r\n\r\n2.0.0 | Performance studio\r\nCatalog, local profiles, session restore, protected startup controls, temp quarantine, resource snapshots and network diagnostics. Game-config editing locked by default.\r\n\r\n1.0.0 | Baseline\r\nHardware scan, reversible preferences, five game checklists, optional config previews, background app controls and CSV comparison.\r\n\r\nUPDATE CHANNEL\r\nLocal release import only. No update server or signing certificate has been provisioned. EXE metadata and SHA-256 detect identity mistakes/corruption, not a trustworthy publisher. Only import a release received from a source you trust. Settings remain in this Windows account's LocalAppData\\FramePilot folder. Copy only the EXE to share; never share your personal recovery folder.\r\n\r\nDRIVER RECOVERY\r\nWindows may not retain a previous driver. Device Manager > device > Properties > Driver > Roll Back Driver is available only when Windows has a rollback package. Otherwise download a compatible older driver from the manufacturer and use its supported installer. PnPUtil export excludes inbox drivers and is not a full system or vendor installer backup. Do not force-delete storage, input, network or security drivers.\r\n\r\nIMPACT LABELS\r\nHigh/Medium/Low describe conditional potential, not a measured gain or confidence score. FPS % and input-latency milliseconds remain unknown until measured. Frame-time differences are not end-to-end latency. Use Compare runs with the same scene and one change at a time.";
 }
}



